<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import http from '../api/http';import PublicState from './PublicState.vue';const loading=ref(true),error=ref(''),items=ref<any[]>([]);const roots=computed(()=>items.value.filter(x=>!x.parentId));onMounted(async()=>{try{items.value=(await http.get('/public/departments')).data.data;}catch(e:any){error.value=e.message??'加载失败';}finally{loading.value=false;}});</script><template><section class="page"><h1>医疗科室</h1><PublicState :loading="loading" :error="error" :empty="!items.length"><div v-for="root in roots" :key="root.id" class="detail"><router-link :to="`/departments/${root.id}`"><h2>{{root.name}}</h2></router-link><p>{{root.introduction||'科室介绍待完善'}}</p><div class="children"><router-link v-for="child in items.filter(x=>x.parentId===root.id)" :key="child.id" :to="`/departments/${child.id}`">{{child.name}}</router-link></div></div></PublicState></section></template>
